                /** @description Workflow stages to keep, as an OR-set: repeat the key to widen it (`?status=Draft&status=Triage`). A single value binds to a one-element set. */
                status?: components["schemas"]["RequisitionStatus"][];
                /** @description Requisition type. */
                type?: components["schemas"]["RequisitionType"];
                /** @description Exact accounting competency (`YYYY-MM`): keeps requisitions whose [start, end] window covers that month. Takes precedence over CompetencyFrom/CompetencyTo when both are supplied. */
                competency?: string;
                /** @description Start of a competency range (`YYYY-MM`), inclusive. Keeps requisitions that are still open or that end on or after this month. Ignored when Competency is supplied. */
                competencyFrom?: string;
                /** @description End of a competency range (`YYYY-MM`), inclusive. Keeps requisitions that start on or before this month. Ignored when Competency is supplied. */
                competencyTo?: string;
                /** @description Free-text search over description, requisition code (with or without the leading `#`), vendor name and vendor CNPJ/CPF. Case-insensitive. */
                search?: string;
                /** @description Lower bound (inclusive) for the estimated value, in BRL. */
                minValue?: number;
                /** @description Upper bound (inclusive) for the estimated value, in BRL. */
                maxValue?: number;
                /** @description Sort field: `code`, `estimate`, `competency`, `status` (workflow pipeline order) or `createdAt`. Prefix with `-` for descending. Defaults to company then code, both descending. */
                sort?: string;
                /** @description Keep only requisitions created by the authenticated caller (requester dashboard). The owner is resolved server-side from the token, never from the query string. */
                mine?: boolean;
                /** @description Keep only post-approval requisitions still missing a fiscal document — either nothing attached yet, or Accounting explicitly asked for it (AwaitingFiscalDocument). */
                awaitingNf?: boolean;
                /** @description Page to return, 1-based. Omitted or below 1 falls back to the first page. */
